import numpy as np

def is_good(g, points):
    # Condition (1): g(ab) = 0 => g(a) = 0 or g(b) = 0
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            a = points[i]
            b = points[j]
            if a != b:
                ab = a * b
                if ab in points:
                    if g(ab) == 0:
                        if g(a) != 0 and g(b) != 0:
                            return False
                # Actually, condition (1) is for any two distinct real numbers a, b.
                # But we can only check on the points we have.

    # Condition (2): g(ab) != 0 => (g(a)-g(b))/(a-b) = g(a)g(b)/g(ab)
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            a = points[i]
            b = points[j]
            if a != b:
                ab = a * b
                if ab in points:
                    if g(ab) != 0:
                        lhs = (g(a) - g(b)) / (a - b)
                        rhs = (g(a) * g(b)) / g(ab)
                        if not np.isclose(lhs, rhs):
                            return False
    # Condition (3): g(1) = 1
    if g(1) != 1:
        return False
    return True

# Let's try some simple functions
def g1(x): return x
def g2(x): return x**2
def g3(x): return 1
def g4(x): return 1/x

points = [1, 2, 3, 4, 5, 6]
print(f"g1: {is_good(g1, points)}")
print(f"g2: {is_good(g2, points)}")
print(f"g3: {is_good(g3, points)}")
print(f"g4: {is_good(g4, points)}")
